insert into public.content_translations (entity, entity_id, locale, field, value) values
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','fr','title',$j$"La Route du Feu : exploration de la Fageda d'en Jordà et de Castellfollit de la Roca"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','fr','area',$j$"La Garrotxa"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','fr','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelone (métro L1 Arc de Triomf). Arrivez 15 minutes à l'avance."$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','fr','inclusions',$j$["Autocar aller-retour depuis Barcelone", "Guide accompagnateur"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','fr','exclusions',$j$["Repas et boissons"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','fr','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🌋 Fageda d'en Jordà : un mystère géologique pour votre groupe", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "La hêtraie de la Fageda d'en Jordà n'est pas une forêt comme les autres : c'est une ", "type": "text"}, {"text": "zone d'exploration géologique unique", "type": "text", "marks": [{"type": "bold"}]}, {"text": " reposant sur une ancienne coulée de lave solidifiée issue du volcan Croscat. Située à 550 mètres d'altitude, elle offre un terrain inhabituel et rare dans la péninsule Ibérique. Faisant partie de la comarque de La Garrotxa, nous sommes entourés de 21 cratères volcaniques, une particularité qui inspire l'aventure et la découverte. Ce cadre a inspiré artistes et historiens.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🔥 Le volcan de Santa Margarida : cohésion d'équipe dans le cratère", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Dans ce cadre volcanique impressionnant, nous mettons en avant le ", "type": "text"}, {"text": "volcan de Santa Margarida", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Son éruption a laissé un cratère large et circulaire, à l'intérieur duquel se trouve un ermitage roman. Au-delà de la prairie qui occupe aujourd'hui le cratère, le reste du volcan est couvert de forêts de feuillus. Notre parcours d'exploration vous mène jusqu'à l'aire de Santa Margarida (en suivant une partie de l'itinéraire 3), un tronçon idéal pour réaliser des ", "type": "text"}, {"text": "activités de team building", "type": "text", "marks": [{"type": "bold"}]}, {"text": " et percevoir la véritable essence de cette région.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🧱 Castellfollit de la Roca : le bastion de basalte", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Perché au bord d'une falaise de basalte de 50 mètres de haut sculptée par la rivière Fluvià, ", "type": "text"}, {"text": "Castellfollit de la Roca", "type": "text", "marks": [{"type": "bold"}]}, {"text": " est l'un des plus petits et des plus fascinants villages de la province de Gérone. Le village repose sur deux coulées de lave superposées qui lui donnent une silhouette spectaculaire. Son centre ancien, construit en pierres volcaniques, nous ramène au XIe siècle et permet à notre groupe d'explorer l'histoire depuis la rue principale jusqu'au belvédère Josep Pla. ", "type": "text"}, {"text": "C'est la conclusion parfaite d'une journée d'exploration géologique.", "type": "text", "marks": [{"type": "bold"}]}]}]}]}$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','fr','title',$j$"Le Défi des Pyrénées : exploration de Queralbs et de la mythique Vall de Núria"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','fr','area',$j$"Ripollès"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','fr','difficulty',$j$"Moyen (randonnée facultative)"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','fr','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelone (métro L1 Arc de Triomf). Arrivez 15 minutes à l'avance."$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','fr','inclusions',$j$["Autocar aller-retour depuis Barcelone", "Guide accompagnateur", "Billet de train à crémaillère aller-retour", "Télécabine dans la Vall de Núria"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','fr','exclusions',$j$["Repas et boissons"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','fr','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏔️ Queralbs : le trésor de pierre des Pyrénées", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Notre point de départ est ", "type": "text"}, {"text": "Queralbs", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un trésor historique situé à 1 220 mètres d'altitude dans la comarque du Ripollès. Avec ses maisons de pierre aux toits d'ardoise, Queralbs est l'un des villages les plus pittoresques des Pyrénées catalanes. Documenté depuis l'an 839, ce village offre un aperçu de l'histoire locale. Nous y explorerons son patrimoine, en particulier l' ", "type": "text"}, {"text": "église de Sant Jaume (Xe s.)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " et sa mairie, qui préparent notre groupe à la grande ascension.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚠 Vall de Núria : l'aventure à 2 000 mètres (en équipe uniquement !)", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "L'activité principale est l'ascension jusqu'à la ", "type": "text"}, {"text": "Vall de Núria", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un cadre idyllique à presque 2 000 mètres d'altitude, entouré de sommets qui atteignent les 3 000 mètres. Cette vallée est l'un des paysages les plus emblématiques et les plus beaux de Catalogne. Ici, votre groupe pourra pratiquer toutes sortes de ", "type": "text"}, {"text": "sports d'aventure, randonnées et activités de cohésion", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". En plus de visiter l'historique sanctuaire de Núria, ce cadre offre l'occasion parfaite d'une exploration en équipe.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚂 Logistique et ascension : le train à crémaillère", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Pour monter dans la vallée, nous utiliserons le ", "type": "text"}, {"text": "train à crémaillère", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", l'accès en voiture n'étant pas autorisé, ce qui garantit une logistique de transport organisée et efficace pour notre groupe de 55 personnes. Pour les plus aventureux, il est possible de monter à pied depuis Queralbs sur un parcours d'environ 4 heures (niveau moyen, 800 m de dénivelé). ", "type": "text"}, {"text": "Le billet du train à crémaillère et la montée en télécabine dans la Vall de Núria sont inclus dans le prix", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", pour que vous profitiez des vues sans rien payer de plus.", "type": "text"}]}]}]}$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','fr','title',$j$"Le cœur sauvage des Pyrénées : Aigüestortes et le lac de Sant Maurici"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','fr','area',$j$"Pallars"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','fr','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelone (métro L1 Arc de Triomf). Arrivez 15 minutes à l'avance."$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','fr','inclusions',$j$["Autocar aller-retour depuis Barcelone", "Guide accompagnateur", "Taxi 4x4 Espot – Estany de Sant Maurici"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','fr','exclusions',$j$["Repas et boissons"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','fr','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏞️ Aigüestortes : le seul parc national de Catalogne", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Tripcelona vous invite à une aventure au cœur des Pyrénées centrales, dans le parc national d'Aigüestortes i Estany de Sant Maurici.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Déclaré parc national le 21 octobre 1955, c'est le seul parc national de Catalogne et l'un des plus emblématiques d'Espagne. Il occupe plus de 40 000 hectares dans la province de Lleida, à cheval sur l'Alta Ribagorça, le Pallars Sobirà, le Pallars Jussà et le Val d'Aran.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "💧 La célèbre route des « Eaux sinueuses »", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Le nom du parc, ", "type": "text"}, {"text": "\"Aigüestortes\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", signifie littéralement ", "type": "text"}, {"text": "« Eaux sinueuses »", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", en référence aux nombreuses rivières, ruisseaux et canaux qui serpentent dans ses vallées et créent des paysages uniques. Le parc est d'origine glaciaire et offre à votre groupe une expérience d'exploration incomparable, avec ", "type": "text"}, {"text": "plus de 200 lacs (estanys)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", de denses forêts de sapins et de hêtres, et des sommets dépassant les ", "type": "text"}, {"text": "3 000 mètres", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Sant Maurici et Els Encantats : le symbole de l'expédition", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Le lieu le plus emblématique du parc est l' ", "type": "text"}, {"text": "Estany de Sant Maurici", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". La beauté de la baie est rehaussée par les majestueux ", "type": "text"}, {"text": "Encantats", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", deux montagnes jumelles aux formes pointues qui dominent le paysage et se dressent à ", "type": "text"}, {"text": "1 910 mètres d'altitude", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Dans ce cadre, nous organisons des parcours de randonnée et de photographie idéaux pour le ", "type": "text"}, {"text": "Team Building", "type": "text", "marks": [{"type": "bold"}]}, {"text": " et l'immersion totale dans la nature sauvage des Pyrénées.", "type": "text"}]}]}]}$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','title',$j$"Le canyon du Vero : Alquézar et la route des passerelles"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','area',$j$"Huesca (Aragon)"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','difficulty',$j$"Facile à modéré"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelone (métro L1 Arc de Triomf). Arrivez 15 minutes à l'avance."$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','inclusions',$j$["Autocar aller-retour depuis Barcelone", "Guide accompagnateur"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','exclusions',$j$["Repas et boissons"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','packing_list',$j$["Chaussures de randonnée", "Vêtements chauds"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','fr','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏰 Alquézar : la cité médiévale suspendue au-dessus du canyon", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Nous passons en Aragon pour rejoindre ", "type": "text"}, {"text": "Alquézar", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", au cœur du Somontano et du ", "type": "text"}, {"text": "parc naturel de la Sierra et des Canyons de Guara", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Considéré comme l'un des plus beaux villages d'Espagne, Alquézar s'élève sur un rocher, couronné par sa ", "type": "text"}, {"text": "collégiale de Santa María", "type": "text", "marks": [{"type": "bold"}]}, {"text": " et les vestiges de son château d'origine musulmane. En groupe, nous parcourrons ses rues pavées, ses places à arcades et ses belvédères sur le canyon avant de descendre jusqu'à la rivière.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🌉 La route des passerelles : marcher au-dessus de la rivière Vero", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "La grande aventure de la journée est la ", "type": "text"}, {"text": "route des passerelles de la rivière Vero", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un parcours circulaire sur des passerelles métalliques ancrées aux parois du canyon, des escaliers et des ponts suspendus au-dessus d'eaux turquoise. Nous descendrons jusqu'au fond du canyon, passerons près de cascades et de barrages centenaires et marcherons sous d'énormes abris sous roche. C'est une route spectaculaire à faire en équipe, pleine de recoins pour les plus belles photos de groupe.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🦅 Sierra de Guara : nature sauvage et vautours fauves", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Pendant le parcours, il est fréquent de voir des ", "type": "text"}, {"text": "vautours fauves", "type": "text", "marks": [{"type": "bold"}]}, {"text": " survoler le canyon. Nous ferons une pause pour déjeuner (repas non inclus : vous pouvez apporter un pique-nique ou manger dans les bars et restaurants du village) et aurons du temps libre pour profiter d'Alquézar avant de rentrer à Barcelone.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚌 Logistique : une journée complète sans souci", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Nous partons en autocar de l'Estació del Nord et arrivons à Alquézar en 3 heures environ, avec une pause technique en chemin. Notre guide accompagne le groupe toute la journée. ", "type": "text"}, {"text": "En hiver, l'ouverture des passerelles dépend de la météo et du débit de la rivière", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": s'il n'est pas possible de les parcourir, nous ferons un itinéraire alternatif par les belvédères et les sentiers du canyon du Vero.", "type": "text"}]}]}, {"type": "paragraph", "content": [{"text": "Photos : FrDr, Robot8A, Mikipons, McBodes, Augustin Liviu, Alberto-g-rovi, Pedro José Ponce Asensio, Enric, LSanzSal — Wikimedia Commons (licences CC BY / CC BY-SA).", "type": "text"}]}]}$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','fr','title',$j$"La magie rurale de la Catalogne : escapade à Rupit et Tavertet"$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','fr','area',$j$"Osona"$j$::jsonb),
