('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','fr','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏰 Rupit : le joyau médiéval du Collsacabra", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Notre exploration commence à ", "type": "text"}, {"text": "Rupit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un charmant village médiéval reconnu dans le monde entier (ONU Tourisme l'a inclus parmi les « Best Tourism Villages », les meilleurs villages touristiques du monde). En parcourant Rupit, votre groupe se plongera dans un cadre naturel spectaculaire où le temps semble s'être arrêté. C'est une expérience d'immersion culturelle, avec ses ruelles étroites, ses maisons de pierre et ses ponts suspendus qui invitent à l'exploration historique. Rupit n'est pas seulement un lieu, c'est un pas en arrière dans l'histoire rurale catalane.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Tavertet : le belvédère géographique suspendu", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "L'aventure atteint son apogée à ", "type": "text"}, {"text": "Tavertet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un village impressionnant situé au sommet d'un ", "type": "text"}, {"text": "promontoire naturel (falaise)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Cet emplacement géographique unique fait de Tavertet un belvédère inégalable. D'ici, votre groupe profitera de ", "type": "text"}, {"text": "vues panoramiques", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sur les vastes réservoirs de ", "type": "text"}, {"text": "Sau", "type": "text", "marks": [{"type": "bold"}]}, {"text": " et ", "type": "text"}, {"text": "Susqueda", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", et pourra contempler la majesté de la chaîne du ", "type": "text"}, {"text": "Montseny", "type": "text", "marks": [{"type": "bold"}]}, {"text": " à l'horizon. Cet endroit est idéal pour réfléchir à la grandeur de la nature catalane et prendre de superbes photos de groupe.", "type": "text"}]}]}]}$j$::jsonb),
