('page','4ff03b67-9d9e-42e6-b046-5c650dcc6c80','fr','content',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Conditions générales de vente", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dernière mise à jour : 25 octobre 2026", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ces conditions régissent l'achat d'excursions et d'activités via ", "type": "text"}, {"text": "tripcelona.com", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Pour réserver, vous devez les lire et les accepter en cochant la case correspondante avant de payer.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "1. Coordonnées du vendeur", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Titulaire :", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"titular\"] (nom commercial : Tripcelona)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "NIF :", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"nif\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Adresse :", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"domicilio\"], Espagne", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "E-mail :", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"email\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Téléphone :", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"telefono\"]", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Tripcelona opère depuis l'Espagne.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "2. Services", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Tripcelona organise des excursions guidées d'une journée et des activités de groupe en Catalogne, au départ de Barcelone. Les excursions n'incluent pas l'hébergement et durent moins de 24 heures.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "La fiche de chaque excursion indique la date, l'heure et le point de départ, l'itinéraire, ce qui est inclus et ce qui ne l'est pas, le nombre de places et le prix.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "3. Processus d'achat", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choisissez l'excursion et cliquez sur ", "type": "text"}, {"text": "« Réserver une place »", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Vérifiez le panier : excursion, date, nombre de places et prix total.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Renseignez les données des participants dans le formulaire de paiement.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cochez la case d'acceptation de ces conditions et de la politique de confidentialité.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Payez par carte sur la passerelle sécurisée de la banque.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Une fois le paiement effectué, vous recevrez un e-mail avec la confirmation de la réservation et votre billet. Si vous ne le recevez pas sous 24 heures, écrivez-nous à [tripola dato=\"email\"].", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "4. Prix", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Tous les prix sont indiqués en ", "type": "text"}, {"text": "euros (€, EUR)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " et incluent la TVA et les taxes applicables. Le prix final est affiché avant de confirmer le paiement et aucun frais ultérieur n'est ajouté.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "5. Moyens de paiement", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Le paiement s'effectue au moment de la réservation par ", "type": "text"}, {"text": "carte de crédit ou de débit (Visa, Mastercard ou Maestro)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " via le TPV virtuel sécurisé de notre établissement bancaire (Redsys). Le paiement est chiffré et peut nécessiter une authentification de votre banque (3D Secure).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tripcelona ne reçoit ni ne conserve les données de votre carte : elles sont saisies directement sur la passerelle de paiement de la banque.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "6. Prestation du service", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Ce service ne comporte aucun envoi physique. La confirmation et le billet sont envoyés par e-mail et le service est fourni le jour de l'excursion, au point de rendez-vous et à l'heure indiqués sur la fiche. Il est recommandé d'arriver 15 minutes avant le départ.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "7. Annulation par le client", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Plus de 15 jours avant l'excursion :", "type": "text", "marks": [{"type": "bold"}]}, {"text": " remboursement de 100 % du montant.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "15 jours ou moins avant l'excursion, ou absence :", "type": "text", "marks": [{"type": "bold"}]}, {"text": " aucun remboursement.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Pour annuler, écrivez à [tripola dato=\"email\"] en indiquant le numéro de commande. Vous pouvez céder votre place à une autre personne sans frais en nous prévenant au moins 10 jours avant l'excursion.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Plus de détails dans la ", "type": "text"}, {"text": "Politique d'annulation et de remboursement", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/politica-de-devoluciones"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "8. Annulation ou modifications par Tripcelona", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Tripcelona peut annuler ou modifier la date d'une excursion en raison du mauvais temps, pour des raisons de sécurité ou parce que le nombre minimum de participants indiqué sur la fiche n'est pas atteint. Dans ce cas, nous vous préviendrons dès que possible et vous pourrez choisir entre une nouvelle date ou le remboursement de 100 % du montant.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "9. Droit de rétractation", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Conformément à l'article 103.l) du Real Decreto Legislativo 1/2007 (loi générale pour la défense des consommateurs et des usagers), le droit de rétractation de 14 jours ne s'applique pas aux services d'activités de loisirs dont la date d'exécution est précise, comme nos excursions. Les annulations sont régies par le point 7.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "10. Remboursements", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Les remboursements s'effectuent sur la carte utilisée pour le paiement, dans un délai maximum de 14 jours à compter de leur approbation. Le délai d'apparition du montant sur votre compte dépend de votre banque.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "11. Service client et réclamations", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Vous pouvez nous contacter par e-mail à [tripola dato=\"email\"] ou par téléphone et WhatsApp au [tripola dato=\"telefono\"]. Nous répondons dans un délai maximum de 48 heures ouvrables.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Des formulaires officiels de plainte et de réclamation de la Generalitat de Catalunya sont à votre disposition : demandez-les par e-mail et nous vous les enverrons. Vous pouvez également vous adresser à l'Agència Catalana del Consum ou au bureau de la consommation de votre commune.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "12. Protection des données", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Nous traitons vos données pour gérer la réservation, comme expliqué dans la ", "type": "text"}, {"text": "Politique de confidentialité", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/politica-de-privacidad"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "13. Droit applicable et juridiction", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Ces conditions sont régies par le droit espagnol. Pour tout litige, les tribunaux du domicile du consommateur sont compétents.", "type": "text"}]}]}$j$::jsonb),
('page','d23cdaa0-478b-4875-b5c0-e0980572cf24','fr','title',$j$"À propos de nous"$j$::jsonb),
('page','d23cdaa0-478b-4875-b5c0-e0980572cf24','fr','seo_title',$j$"À propos | Agence de voyages et logistique pour grands groupes"$j$::jsonb),
('page','d23cdaa0-478b-4875-b5c0-e0980572cf24','fr','seo_description',$j$"Notre mission : une agence de voyages spécialisée dans les parcours d'exploration. Nous dirigeons la logistique des grands groupes et du team building avec des experts locaux."$j$::jsonb),
('page','d23cdaa0-478b-4875-b5c0-e0980572cf24','fr','content',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Voyager et explorer ensemble : une logistique d'élite pour votre grand groupe", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ce que vous pouvez attendre ↓ Vision et mission Galerie d'aventures", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Faites-nous confiance : votre voyage est couvert", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Cancelación Flexible para Grupos", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-021.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Annulation flexible pour les groupes", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Des politiques claires et transparentes pour les grands groupes. Nous proposons des conditions d'annulation flexibles adaptées aux besoins logistiques de votre nombre de voyageurs.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Reserva 100% Asegurada", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-022.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Réservation 100 % sécurisée", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Processus de paiement sécurisé et chiffré pour toutes les transactions. Votre investissement est protégé, et nous garantissons la confirmation immédiate de tous les services.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Salud y Seguridad Prioritaria", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-023.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "La santé et la sécurité avant tout", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Des protocoles rigoureux et des guides formés aux premiers secours. Nous veillons au bien-être de chacun des 55 membres du groupe pendant toute l'aventure.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Calidad y Servicio de Confianza", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-024.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Qualité et service de confiance", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Très appréciés de nos clients entreprises et incentives. Notre engagement est l'excellence dans la gestion et la réalisation de grands événements.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Asistencia Local Permanente", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-025.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Assistance locale permanente", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Une équipe de soutien dédiée à Barcelone pour votre groupe. Assistance 24 h/24, 7 j/7 et aide locale immédiate en cas d'imprévu logistique ou de coordination.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Punto de encuentro para la aventura en Plaza Espanya, Barcelona.", "src": "https://tripcelona.com/wp-content/uploads/2025/11/vall-de-nuria-prin-scaled.jpg", "title": null}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Notre vision", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Inspirer des aventures collectives grâce à une logistique d'élite à Barcelone", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Notre vision en tant qu' ", "type": "text"}, {"text": "entreprise d'excursions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " est de transformer la façon dont les grands groupes découvrent Barcelone. Nous voulons que chaque aventure soit une expérience d'exploration cohésive.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Notre mission", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Proposer des solutions de voyage sur mesure et des parcours d'exploration impeccables", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Notre mission est double : d'abord, veiller à ce que chaque parcours d'exploration soit conçu sur mesure, en privilégiant le ", "type": "text"}, {"text": "Team Building", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Ensuite, garantir une logistique impeccable pour les grands groupes, couvrant le transport et la sécurité selon les normes les plus élevées.\"", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Tripcelona: Pedraforca, Arc de Triomf, Montjuïc y Montserrat", "src": "https://tripcelona.com/wp-content/uploads/2026/10/tripcelona-collage.jpg", "title": null}}, {"type": "paragraph", "content": [{"text": "0 %", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Satisfaction en logistique", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "0 +", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Grands groupes gérés", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "0 +", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Parcours d'exploration uniques", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "0 / 7", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Assistance locale garantie", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Grupo explorando Búnkers del Carmel. Rutas de Aventura Barcelona.", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Untitled-design-11.png", "title": null}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Le parcours d'exploration ultime", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tripcelona met votre grand groupe en contact avec l'essence cachée de Barcelone.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Faites confiance à nos experts locaux primés pour concevoir une expérience d'exploration personnalisée, inoubliable et avec une logistique garantie pour tous.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hébergement pour groupes", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Expériences d'exploration exclusives", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Planification de voyages sur mesure", "type": "text"}]}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Transport privé inclus", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Recommandations locales authentiques", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Support logistique 24 h/24, 7 j/7", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Notre galerie", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Grupo de viaje explorando la naturaleza en Cataluña", "src": "https://tripcelona.com/wp-content/uploads/2025/11/travelportjpg-77.jpg", "title": null}}, {"type": "image", "attrs": {"alt": "Paisaje de montaña en una ruta de exploración por Cataluña", "src": "https://tripcelona.com/wp-content/uploads/2025/11/portada-1668x1080-1.jpg", "title": null}}, {"type": "image", "attrs": {"alt": "Reto del Pirineo. Senderismo Vall de Núria y Queralbs para grupos.", "src": "https://tripcelona.com/wp-content/uploads/2025/11/cami-de-queralbs-a-nuria-per-daio.jpg", "title": null}}, {"type": "image", "attrs": {"alt": "Paisaje volcánico de La Garrotxa", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Garrotxa-4-1-scaled-1.jpg", "title": null}}]}$j$::jsonb)
